int handle_rfcomm_receive(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t size, int flags) {
    int bytes_received = 0;

    /* Check if RFCOMM connection setup is deferred and accept it if so. */
    if (rfcomm_deferred_setup_pending(sock)) {
        rfcomm_accept_deferred_setup(sock);
    }

    /* Call lower-level function to receive the message. */
    bytes_received = rfcomm_receive_message(iocb, sock, msg, size, flags);

    if (bytes_received > 0) {
        /* Update the socket's receive memory allocation. */
        sock_update_rcv_mem_usage(sock, bytes_received);

        /* Unthrottle the connection if memory usage is below a certain threshold. */
        if (sock_rcv_mem_usage_below_threshold(sock)) {
            rfcomm_unthrottle_connection(sock);
        }
    }

    return bytes_received;
}
